module Admin
  # What a Liquid template is allowed to see, generated by reflecting on the
  # Drop classes themselves.
  #
  # Written down by hand it would drift: someone adds a method and the AI never
  # learns about it, or removes one and the AI keeps trying. Reading the classes
  # means the reference cannot be wrong.
  class DropReference
    # Each entry: the drop, how a template reaches it, and what it is for.
    ROOTS = {
      "page"       => [PageDrop, "the page being rendered"],
      "site"       => [SiteDrop, "the parish, and the live data feeds"],
      "nav"        => [NavDrop, "each top-level navigation entry (an array)"],
      "section"    => [SectionDrop, "a horizontal band (inside the page template)"],
      "block"      => [BlockDrop, "one piece of content (inside the section template)"],
      "photo"      => [PhotoDrop, "a photograph, via block.photo or page.hero_photo"]
    }.freeze

    NESTED = {
      "site.calendar"   => [CalendarDrop,   "parish calendar, grouped into weeks"],
      "site.upcoming"   => [UpcomingDrop,   "notable events in the coming week"],
      "site.recordings" => [RecordingsDrop, "recordings of the adult education classes"],
      "site.lectionary" => [LectionaryDrop, "today's appointed readings"],
      "site.calendar.weeks[]" => [CalendarDrop::WeekDrop, "one week of the calendar"],
      "site.recordings.all[]" => [RecordingsDrop::RecordingDrop, "one recording"],
      "site.lectionary.today"  => [LectionaryDrop::DayDrop, "one day's readings"],
      "site.lectionary.today.appointed[]" => [LectionaryDrop::ReadingDrop, "one reading"]
    }.freeze

    def self.call
      {
        choosing_how_to_style: CHOOSING,
        rules: RULES,
        # Learned in use rather than reviewed into the code. See Lesson.
        learned: Lesson.for_guide,
        objects: (ROOTS.merge(NESTED)).map { |path, (klass, purpose)|
          { path: path, purpose: purpose, properties: properties(klass) }
        }
      }
    end

    def self.properties(klass)
      (klass.public_instance_methods(false) - [:initialize])
        .reject { |m| m.to_s.end_with?("?") }   # Liquid cannot call these
        .map(&:to_s).sort
    end
    private_class_method :properties

    # How to make something look different. Without this the AI invents a block
    # kind for every one-off, and in two years there are forty of them that
    # nobody can tell apart -- the entropy failure docs/ai-admin.md warns about.
    #
    # The person asking knows nothing about blocks, templates or CSS. They say
    # "the heading here should feel more formal". Choosing the mechanism is your
    # job, and the cheapest one that works is the right one.
    CHOOSING = [
      "ONE thing on ONE page looks different -> give that block a css_class " \
      "(update_block css_class: \"lead\") and write one CSS rule for it. Cheapest, " \
      "and leaves nothing behind for anyone to maintain.",

      "EVERYTHING of a sort on ONE page looks different -> write CSS scoped to the " \
      "page: .page-donate .b-heading { ... }. Every page carries a class on <body> " \
      "built from its slug, so this is stable.",

      "EVERYTHING of a sort EVERYWHERE looks different -> change the stylesheet, or " \
      "the template if the markup itself must change. Say plainly that it affects " \
      "the whole site, because the person asking may be thinking of one page.",

      "A genuinely NEW SORT of thing, with its own structure -> then and only then " \
      "create a block kind with add_template. A new kind is right when the markup " \
      "differs (a quotation with an attribution line, a card with a caption under " \
      "it). It is WRONG when only the look differs -- that is what the first two " \
      "options are for.",

      "Before inventing a kind, ask whether this is the THIRD time you have wanted " \
      "it. Twice is a coincidence; three times is a pattern worth naming.",

      "NEVER write CSS against a section or block id. A revision copies every row, " \
      "so ids change on every publish and the rule would silently stop working. " \
      "Page classes follow the slug and are stable; css_class is yours to set."
    ].freeze

    # Everything below was learned the hard way porting this site off ERB. Each
    # line is a bug that shipped.
    RULES = [
      "An empty string is TRUE in Liquid. Only nil and false are falsy. To test " \
      "whether something has content, use {% if thing != blank %}, not {% if thing %}. " \
      "Most drops here already return nothing for blank values, but do not rely on it.",

      "Nesting uses {% include 'name' %}, which SHARES the surrounding scope — so " \
      "`block`, `section` and `site` are already visible and need not be passed. " \
      "{% include %} also takes a variable: {% include block.template %} is how a block " \
      "finds its own template, which is why there is no dispatcher to maintain.",

      "{% render %} is the opposite: it isolates scope and requires a quoted literal. " \
      "It cannot contain an {% include %}. This site uses include throughout; prefer it.",

      "Liquid does NOT escape output. Text that lands inside an HTML attribute must " \
      "be escaped: alt=\"{{ photo.alt }}\" is already safe because the drop escapes it, " \
      "but anything you interpolate yourself needs | escape.",

      "ALWAYS quote attribute values. Writing data-action={{ x }} unquoted truncates " \
      "at the first > and silently breaks the attribute. This happened on the real site.",

      "Templates are named like paths — 'block/heading', 'header', 'page' — but they " \
      "are database rows. {% include 'block/heading' %} loads the row of that name.",

      "A block kind renders through the template named block/<kind>. Adding a new " \
      "kind means creating a template with the matching name; there is no code to change.",

      "You cannot call Ruby. You can only read the properties listed below. If " \
      "something you need is not here, say so — it needs a developer to expose it."
    ].freeze
  end
end
